// ====================================================
// PREPARAR PARÁMETROS — Schema real del frontend kiosk
// ====================================================
const body = $input.first().json.body || $input.first().json || {};

// Campos básicos
const empleado_id = parseInt(body.empleado_id);
const empleado_nombre = String(body.empleado_nombre || '');
const tipo = String(body.tipo || '').toLowerCase();
const timestamp_iso = body.timestamp || new Date().toISOString();

// Coordenadas (frontend manda lat/lng, NO latitud/longitud)
const lat = (body.lat !== undefined && body.lat !== null) ? parseFloat(body.lat) : null;
const lng = (body.lng !== undefined && body.lng !== null) ? parseFloat(body.lng) : null;

// Geo info
const geo_autorizada = body.geo_autorizada !== false; // default true
const geo_sitio = String(body.geo_sitio || '');
const geo_distancia = parseInt(body.geo_distancia) || 0;
const geo_motivo = String(body.geo_motivo || '');
const geo_status = String(body.geo_status || (geo_autorizada ? 'autorizado' : 'pendiente_aprobacion'));

// SO (solo en salida)
const so_id = body.so_id ? parseInt(body.so_id) : null;
const so_nombre = String(body.so_nombre || '');

// Bolsa / cuenta indirecta (Fase 1.5 Parte 10 — solo en salida cuando se confirma bolsa)
const cuenta_id = body.cuenta_id ? parseInt(body.cuenta_id) : null;
const cuenta_nombre = String(body.cuenta_nombre || '');

// Supervisor info (informativo, va a chatter)
const supervisor_nombre = String(body.supervisor_nombre || '');

// Estimado (olvidé checar entrada)
const es_estimado = body.es_estimado === true;
const motivo_estimado = String(body.motivo_estimado || '');

// Validación mínima
const TIPOS_VALIDOS = ['entrada', 'salida', 'salida_comida', 'regreso_comida'];
if (!empleado_id || !tipo || !TIPOS_VALIDOS.includes(tipo)) {
  return [{
    json: {
      _error: true,
      codigo_error: 'DATOS_INCOMPLETOS',
      mensaje: 'Faltan datos requeridos (empleado_id o tipo inválido). Tipo recibido: ' + tipo
    }
  }];
}

// Convertir timestamp del browser a formato Odoo UTC
// Si es_estimado: usar el timestamp del body (la hora declarada)
// Si NO: usar ahora (el browser ya manda la hora actual, pero por consistencia usamos server time)
let fechaParaOdoo;
if (es_estimado) {
  // Frontend manda "2026-04-20T17:00:00" (sin Z, hora local del técnico)
  // Asumimos que es CST (UTC-6) y convertimos a UTC
  const localDate = new Date(timestamp_iso);
  // Si no tiene zona, asumimos local del técnico (CST)
  if (!timestamp_iso.includes('Z') && !timestamp_iso.match(/[+-]\d{2}:?\d{2}$/)) {
    fechaParaOdoo = new Date(localDate.getTime() + (6 * 60 * 60 * 1000));
  } else {
    fechaParaOdoo = localDate;
  }
} else {
  fechaParaOdoo = new Date();
}

const fechaOdooStr = fechaParaOdoo.toISOString().slice(0, 19).replace('T', ' ');

// Para display CST
const fechaCST = new Date(fechaParaOdoo.getTime() - (6 * 60 * 60 * 1000));
const hora_cst = fechaCST.toISOString().substring(11, 16);
const fecha_cst = fechaCST.toISOString().substring(0, 10);

// Ventana de búsqueda de attendances abiertas
// F1.5 fix (2026-05-11): ventana 15 días para consistencia con kiosk/estado-empleado workflow.
// Antes 48h - no detectaba huérfanas >48h y rompía el auto-rescate del Issue 2 (caso Ricardo att 12948 con 95h).
const ahoraUTC = new Date();
const hace15Dias = new Date(ahoraUTC.getTime() - (15 * 24 * 60 * 60 * 1000));
const ventanaInicio = hace15Dias.toISOString().slice(0, 19).replace('T', ' ');

return [{
  json: {
    // Identificación
    empleado_id,
    empleado_nombre,
    tipo,

    // Tiempo
    fechaOdoo: fechaOdooStr,
    hora_cst,
    fecha_cst,
    ventanaInicio,

    // Geo
    lat,
    lng,
    geo_autorizada,
    geo_sitio,
    geo_distancia,
    geo_motivo,
    geo_status,

    // SO
    so_id,
    so_nombre,

    // Bolsa / cuenta indirecta (Fase 1.5 Parte 10)
    cuenta_id,
    cuenta_nombre,

    // Supervisor
    supervisor_nombre,

    // Estimado
    es_estimado,
    motivo_estimado
  }
}];

// B1 #269: si Odoo - Validar empleado falló, su salida de error ya lleva la respuesta y aquí
// llega un item vacío (alwaysOutputData): se corta para no responder dos veces.
// Ojo: si la salida de error viene vacía, .all(1) devuelve la salida normal (medido en ejecución 111545),
// por eso se busca el campo error y no se cuenta.
try { if ($('Odoo - Validar empleado').all(1).some(i => i.json && i.json.error !== undefined && !i.json.id)) return []; } catch (e) {}
// ====================================================
// VALIDAR EMPLEADO (sin PIN — frontend ya validó)
// ====================================================
const params = $('Code - Preparar parámetros').item.json;
const empleados = $input.all().map(item => item.json);

if (empleados.length === 0 || !empleados[0].id) {
  return [{
    json: {
      ...params,
      _error: true,
      codigo_error: 'EMPLEADO_NO_EXISTE',
      mensaje: 'Empleado no encontrado en el sistema (id: ' + params.empleado_id + ')'
    }
  }];
}

const empleado = empleados[0];

if (empleado.active !== true) {
  return [{
    json: {
      ...params,
      _error: true,
      codigo_error: 'EMPLEADO_INACTIVO',
      mensaje: 'Empleado no activo'
    }
  }];
}

// Reusar nombre del frontend si no viene del Odoo
const empleado_nombre_final = params.empleado_nombre || empleado.name;

return [{
  json: {
    ...params,
    empleado_nombre: empleado_nombre_final,
    odoo_employee_data: empleado,
    _valido: true
  }
}];

// ====================================================
// ANALIZAR CANDADOS según TIPO
// Diferencia entrada vs salida vs comida
// F1.5 Issue 2 (2026-05-11): >=16h gatilla AUTO-RESCATE
// ====================================================
const params = $('Code - Validar empleado').item.json;
const tipo = params.tipo;
const attendances = $input.all().map(item => item.json).filter(a => a && a.id);

// Buscar attendances abiertas (sin check_out)
const abiertas = attendances.filter(a => !a.check_out);
const ahoraUTC = new Date();

// =========================================
// CASO: tipo = 'entrada'
// =========================================
if (tipo === 'entrada') {
  // Si NO hay abiertas: continuar con CREATE
  if (abiertas.length === 0) {
    return [{
      json: {
        ...params,
        accion: 'CREATE_ENTRADA',
        attendance_id_pendiente: null,
        auto_rescate_pending: false
      }
    }];
  }

  // Hay abierta: calcular horas
  const pendiente = abiertas.sort((a,b) => new Date(b.check_in) - new Date(a.check_in))[0];
  const checkInPend = new Date(pendiente.check_in.replace(' ', 'T') + 'Z');
  const horasTrans = (ahoraUTC - checkInPend) / (1000 * 60 * 60);

  // Validación candados:
  // - < 6h: bloqueo simple "ya tienes entrada"
  // - 6h-16h: ZONA_GRIS (usar 'olvidé salida' o 'seguí en turno')
  // - >= 16h: AUTO-RESCATE F1.5 (cerrar 9.6h + TAG + incidencia auto_cierre_pendiente, permitir nuevo checkin)
  if (horasTrans < 6) {
    return [{
      json: {
        ...params,
        _error: true,
        codigo_error: 'YA_TIENES_ENTRADA',
        mensaje: 'Ya tienes una entrada registrada hace ' + horasTrans.toFixed(1) + ' hrs.',
        attendance_id_abierto: pendiente.id,
        horas_transcurridas: horasTrans.toFixed(2)
      }
    }];
  } else if (horasTrans < 16) {
    return [{
      json: {
        ...params,
        _error: true,
        codigo_error: 'ZONA_GRIS',
        error_msg: 'ZONA_GRIS:' + horasTrans.toFixed(1),
        mensaje: 'Llevas ' + horasTrans.toFixed(1) + ' hrs desde tu última entrada. ¿Olvidaste checar salida?',
        attendance_id_abierto: pendiente.id,
        horas_transcurridas: horasTrans.toFixed(2)
      }
    }];
  } else {
    // F1.5 Issue 2 — AUTO-RESCATE
    const horasNetas = 9.6;
    const checkOutAutoUTC = new Date(checkInPend.getTime() + horasNetas * 3600 * 1000);
    const checkOutAutoOdoo = checkOutAutoUTC.toISOString().slice(0, 19).replace('T', ' ');
    const incidenciaId = 'INC-AUTO-CIERRE-' + params.empleado_id + '-' + new Date().toISOString().replace(/[:.]/g, '-');
    return [{
      json: {
        ...params,
        accion: 'CREATE_ENTRADA',
        attendance_id_pendiente: pendiente.id,
        auto_rescate_pending: true,
        auto_rescate_check_out: checkOutAutoOdoo,
        auto_rescate_incidencia_id: incidenciaId,
        auto_rescate_check_in_original: pendiente.check_in,
        auto_rescate_horas_originales: horasTrans.toFixed(2)
      }
    }];
  }
}

// =========================================
// CASO: tipo = 'salida'
// =========================================
if (tipo === 'salida') {
  if (abiertas.length === 0) {
    return [{
      json: {
        ...params,
        _error: true,
        codigo_error: 'NO_HAY_ENTRADA',
        mensaje: 'No tienes ninguna entrada abierta para cerrar. Registra una entrada primero.'
      }
    }];
  }

  // Hay abierta: usar la más reciente para cerrar
  const pendiente = abiertas.sort((a,b) => new Date(b.check_in) - new Date(a.check_in))[0];
  const checkInPend = new Date(pendiente.check_in.replace(' ', 'T') + 'Z');
  const horasTrans = (ahoraUTC - checkInPend) / (1000 * 60 * 60);

  return [{
    json: {
      ...params,
      accion: 'UPDATE_SALIDA',
      attendance_id_pendiente: pendiente.id,
      check_in_original: pendiente.check_in,
      horas_transcurridas: horasTrans.toFixed(2)
    }
  }];
}

// =========================================
// CASO: comida (placeholder Fase 1)
// =========================================
if (tipo === 'salida_comida' || tipo === 'regreso_comida') {
  return [{
    json: {
      ...params,
      accion: 'COMIDA_PLACEHOLDER',
      _placeholder: true
    }
  }];
}

// Tipo desconocido
return [{
  json: {
    ...params,
    _error: true,
    codigo_error: 'TIPO_DESCONOCIDO',
    mensaje: 'Tipo de evento no reconocido: ' + tipo
  }
}];

// Armar datos para el flujo post-CREATE entrada
// (v4.1 sin chatter - solo pasa datos al siguiente paso)
const prev = $('Code - Analizar candados').item.json;
const odooResult = $input.first().json;
const attendance_id = odooResult.id;

return [{
  json: {
    ...prev,
    attendance_id_creado: attendance_id
  }
}];

// Armar datos para el flujo post-UPDATE salida
// (v4.1 sin chatter - solo pasa datos al siguiente paso)
// El UPDATE no devuelve el id, usamos el attendance_id_pendiente del prev
const prev = $('Code - Analizar candados').item.json;

return [{
  json: {
    ...prev,
    attendance_id_creado: prev.attendance_id_pendiente
  }
}];

const prev = $input.first().json;
return [{
  json: {
    ...prev,
    success: true,
    placeholder: true,
    mensaje: 'Comida registrada (placeholder Fase 1 - no se persiste en Odoo todavía)',
    tipo: prev.tipo
  }
}];

// Decide si crear incidencia en GitHub
// Casos:
//  - tipo='entrada' Y es_estimado=true  -> ajuste_hora_entrada (legacy schema, incidencias.json)
//  - auto_rescate_pending=true          -> auto_cierre_pendiente (F2.1+ schema, incidencias-asistencia.json)
// F1.5 sub-fix (2026-05-11): rama auto_rescate migrada a schema F2.1+ para que el visor RH la muestre.
const prev = $input.first().json;
const analizado = $('Code - Analizar candados').item.json;
const isAutoRescate = prev.auto_rescate_pending === true || analizado.auto_rescate_pending === true;

if (prev._error === true) {
  return [{ json: { ...prev, _skip_github: true } }];
}

// F1.5 Opcion 2: incidencia auto_cierre_pendiente con schema F2.1+
if (isAutoRescate) {
  const incidencia = {
    id_interno: prev.auto_rescate_incidencia_id || analizado.auto_rescate_incidencia_id,
    tipo: 'auto_cierre_pendiente',
    status: 'pendiente_rh',
    fecha_creacion: new Date().toISOString(),
    empleado_id: analizado.empleado_id,
    empleado_nombre: analizado.empleado_nombre,
    attendance_id_cerrado: analizado.attendance_id_pendiente,
    attendance_id_nuevo: prev.attendance_id_creado || null,
    check_in_original_utc: analizado.auto_rescate_check_in_original,
    check_out_aplicado_utc: analizado.auto_rescate_check_out,
    horas_originales: analizado.auto_rescate_horas_originales,
    motivo: 'Auto-cierre por jornada abierta >16h al siguiente check-in del empleado',
    tag_disputa_activo: true,
    autoincidencia: true,
    rh_aprobo: null,
    rh_fecha: null,
    // Campos F2.1+ que no aplican a auto-incidencias (salta supervisor, va directo a RH)
    department_id: null,
    department_name: null,
    supervisor_id: null,
    supervisor_name: null,
    propuestas: []
  };
  return [{
    json: {
      ...prev,
      ...analizado,
      nueva_incidencia: incidencia,
      _target_file_path: 'shared/incidencias-asistencia.json',
      _skip_github: false
    }
  }];
}

// Caso legacy: solo crear incidencia para entradas estimadas (ajuste_hora_entrada)
if (prev.tipo !== 'entrada' || prev.es_estimado !== true) {
  return [{ json: { ...prev, _skip_github: true } }];
}

const incidencia = {
  id: 'INC-ENT-' + Date.now(),
  tipo: 'ajuste_hora_entrada',
  estado: 'pendiente_supervisor',
  empleado_id: prev.empleado_id,
  empleado_nombre: prev.empleado_nombre,
  attendance_id: prev.attendance_id_creado,
  hora_estimada: prev.fechaOdoo,
  motivo: prev.motivo_estimado || '',
  geo_sitio: prev.geo_sitio || '',
  geo_autorizada: prev.geo_autorizada,
  lat: prev.lat,
  lng: prev.lng,
  fecha_solicitud: new Date().toISOString(),
  supervisor_aprobo: null,
  supervisor_fecha: null,
  rh_aprobo: null,
  rh_fecha: null
};

return [{
  json: {
    ...prev,
    nueva_incidencia: incidencia,
    _target_file_path: 'shared/incidencias.json',
    _skip_github: false
  }
}];

// Mergea la nueva incidencia al archivo existente
// PRESERVA todos los datos del checkin para que Respuesta OK los tenga después del PUT
// F1.5 sub-fix: commit message dinámico por tipo + _target_file_path preservado para HTTP PUT
const ghResp = $input.first().json;
const prev = $('Code - Prep Incidencia').item.json;
const nueva = prev.nueva_incidencia;

let archivo = { incidencias: [], _metadata: { version: '1.0' } };
let sha = null;

if (ghResp && ghResp.content && ghResp.sha) {
  sha = ghResp.sha;
  try {
    const decoded = Buffer.from(ghResp.content.replace(/\n/g, ''), 'base64').toString('utf8');
    archivo = JSON.parse(decoded);
  } catch (e) {
    archivo = { incidencias: [], _metadata: { version: '1.0' } };
  }
}

if (!Array.isArray(archivo.incidencias)) archivo.incidencias = [];

archivo.incidencias.unshift(nueva);

const nuevoStr = JSON.stringify(archivo, null, 2);
const nuevoB64 = Buffer.from(nuevoStr, 'utf8').toString('base64');

const tipoLabel = nueva.tipo || 'sin_tipo';

return [{
  json: {
    // Datos de GitHub PUT (necesarios para el PUT)
    sha: sha || '',
    content: nuevoB64,
    message: 'incidencia: ' + tipoLabel + ' ' + prev.empleado_nombre + ' (id ' + prev.empleado_id + ')',
    _target_file_path: prev._target_file_path,

    // Datos del checkin PRESERVADOS (para Respuesta OK)
    incidencia_id: nueva.id_interno || nueva.id,
    attendance_id_creado: prev.attendance_id_creado,
    empleado_id: prev.empleado_id,
    empleado_nombre: prev.empleado_nombre,
    tipo: prev.tipo,
    hora_cst: prev.hora_cst,
    fechaOdoo: prev.fechaOdoo,
    es_estimado: true,
    geo_sitio: prev.geo_sitio
  }
}];

// Respuesta OK unificada - v4.2
// Hay 3 caminos posibles hacia acá:
// 1. Entrada estimada: pasa por PUT incidencias → llega el output del PUT a $input
//    → los DATOS REALES están en 'Code - Merge incidencia'
// 2. Entrada normal: pasa por Prep Incidencia → skip_github=true → llega directo
//    → los datos están en $input.first()
// 3. Salida: pasa por Armar Datos Salida → llega directo
//    → los datos están en $input.first()
// 4. Comida: placeholder → llega directo

const fromInput = $input.first().json;

// Detectar si venimos del PUT de GitHub (tiene commit/content)
const vinoDelPUT = fromInput && (fromInput.commit || fromInput.content) && !fromInput.tipo;

let data;
if (vinoDelPUT) {
  // Rama de incidencia: leer de Merge incidencia que preservó los datos
  data = $('Code - Merge incidencia').item.json;
} else {
  // Ramas directas
  data = fromInput;
}

const esComida = data.placeholder === true;
const tipo = data.tipo || 'desconocido';

let mensaje;
if (esComida) {
  mensaje = 'Comida registrada (Fase 1 placeholder, no persiste en Odoo)';
} else if (tipo === 'entrada') {
  mensaje = data.es_estimado 
    ? 'Entrada estimada registrada. Pendiente validación del supervisor.'
    : 'Check-in registrado exitosamente';
} else if (tipo === 'salida') {
  mensaje = 'Check-out registrado exitosamente';
} else {
  mensaje = 'Operación completada';
}

return [{
  json: {
    success: true,
    accion_valida: true,
    tipo: tipo,
    attendance_id: data.attendance_id_creado || null,
    empleado_id: data.empleado_id || null,
    empleado_nombre: data.empleado_nombre || null,
    hora_cst: data.hora_cst || null,
    hora_utc: data.fechaOdoo || null,
    es_estimado: data.es_estimado === true,
    incidencia_creada: data.incidencia_id || null,
    placeholder: esComida,
    mensaje: mensaje
  }
}];

// Respuesta de error unificada
const data = $input.first().json;

const response = {
  success: false,
  accion_valida: false,
  codigo_error: data.codigo_error || 'ERROR_DESCONOCIDO',
  mensaje: data.mensaje || 'Error desconocido procesando la solicitud',
  error_msg: data.error_msg || data.mensaje || 'Error desconocido',
  empleado_id: data.empleado_id || null,
  attendance_id_abierto: data.attendance_id_abierto || null,
  horas_transcurridas: data.horas_transcurridas || null
};

return [{ json: response }];

// F1.5 Issue 2 - Restaura params completos después del Odoo close
// para que Switch - Por tipo pueda rutear por params.tipo
const params = $('Code - Analizar candados').item.json;
return [{ json: params }];

// B1 #269: identidad del intento. El kiosko nuevo manda intento_id (UUID); el viejo no, y el
// servidor genera uno propio (mitad tolerante: acepta las dos firmas).
const w = $input.first().json || {};
const body = w.body || {};
const raw = String(body.intento_id || '').trim().toLowerCase();
const valido = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(raw) || /^k-[a-z0-9]{6,12}-[a-z0-9]{6,12}$/.test(raw);
const t0 = Date.now();
return [{ json: {
  intento_id: valido ? raw : 'srv-' + $execution.id,
  intento_cliente: valido,
  empleado_id: parseInt(body.empleado_id) || 0,
  tipo: String(body.tipo || '').toLowerCase(),
  t0,
  inicio_utc: new Date(t0).toISOString(),
  fecha_cst: new Date(t0 - 6 * 3600e3).toISOString().slice(0, 10),
  ejecucion: String($execution.id)
} }];

// B1 #269: idempotencia. Solo un intento guardado como 'ok' se devuelve tal cual.
// Uno 'en_proceso' de hace menos de 60 s responde EN_PROCESO; un error guardado se vuelve a correr.
const ini = $('Code - B1 Inicio').first().json;
const f = ($input.first() && $input.first().json) || {};
let repetido = false, resp = null;
if (ini.intento_cliente && f.intento_id === ini.intento_id) {
  if (f.estado === 'ok') {
    try { resp = JSON.parse(f.respuesta); } catch (e) { resp = null; }
    if (resp && typeof resp === 'object') { repetido = true; resp.idempotente = true; resp.intento_id = ini.intento_id; }
  } else if (f.estado === 'en_proceso' && f.inicio_utc && Date.now() - new Date(f.inicio_utc).getTime() < 60000) {
    repetido = true;
    resp = { success: false, accion_valida: false, codigo_error: 'EN_PROCESO', mensaje: 'Tu checada anterior todavía se está guardando. Espera unos segundos.', intento_id: ini.intento_id, empleado_id: ini.empleado_id };
  }
}
return [{ json: { ...ini, _repetido: repetido, _respuesta: resp } }];

// B1 #269: plazo del servidor. Ninguna escritura a Odoo empieza después de 20 s desde que entró
// la petición: el kiosko ya se habrá rendido y la persona volverá a intentar.
const x = $input.first().json;
const ini = $('Code - B1 Inicio').first().json;
if (x._error !== true && x.accion !== 'COMIDA_PLACEHOLDER' && Date.now() - ini.t0 > 20000) {
  return [{ json: { ...x, _error: true, codigo_error: 'TIEMPO_AGOTADO', mensaje: 'El servidor tardó demasiado y no guardó tu checada. Intenta de nuevo.' } }];
}
return [{ json: x }];

// B1 #269: salida de error de los 4 nodos que escriben o validan en Odoo.
// Convierte la excepción en respuesta legible. Nunca deja la ejecución sin Respond.
const e = $input.first().json || {};
const err = e.error;
const msg = String((err && typeof err === 'object' ? (err.message || err.description) : err) || e.message || 'sin detalle');
const sinRespuesta = /ECONNRESET|ETIMEDOUT|ECONNREFUSED|ENOTFOUND|EAI_AGAIN|socket hang up|timeout|timed out|\b(429|502|503|504)\b/i.test(msg);
let p = {};
try { p = $('Code - Preparar parámetros').first().json || {}; } catch (x) { p = {}; }
const limpio = msg.replace(/^[\s\S]*?(ValidationError|UserError|AccessError|MissingError)[:\s]*/, '').slice(0, 300);
return [{ json: {
  _error: true,
  codigo_error: sinRespuesta ? 'ODOO_NO_RESPONDE' : 'ODOO_RECHAZO',
  mensaje: sinRespuesta
    ? 'Odoo no respondió. Tu checada NO se guardó. Intenta de nuevo en un momento.'
